// === Lecture brute des entités HA ===
// Getters + suivi disponibilité sonde. Pas de logique métier ici.
// PREREQUIS : cocher "Enable global context store" sur le nœud serveur HA.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

let g;
try {
    g = global.get('homeassistant').homeAssistant.states;
    if (!g) throw new Error('states indisponibles');
} catch (e) {
    node.warn('HA indisponible, tick ignoré : ' + e.message);
    return null;
}

const n = (id, def = 0) => {
    const v = parseFloat(g[id]?.state);
    return isNaN(v) ? def : v;
};
const attr = (id, key) => g[id]?.attributes?.[key];
const attrNum = (id, key) => {
    const v = parseFloat(g[id]?.attributes?.[key]);
    return isNaN(v) ? null : v;
};
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

// --- Paramètres utilisateur ---
msg.enabled = g['input_boolean.cumulus_automation_enabled']?.state === 'on';
msg.target = n('input_number.cumulus_target_temp', 55);
msg.minT = n('input_number.cumulus_min_temp', 40);
msg.solarTrig = n('input_number.cumulus_solar_trigger', 1100);
// Bornée : évite division par zéro / valeurs absurdes
msg.eff = clamp(n('input_number.cumulus_efficiency', 0.67), 0.3, 1);
msg.surplusTrig = n('input_number.cumulus_surplus_trigger', 1200);

// Volume du ballon (entité optionnelle, défaut 200 L) → kWh par °C
msg.tankL = clamp(n('input_number.cumulus_tank_volume', 200), 50, 500);
msg.kwhPerDeg = msg.tankL * 4.186 / 3600;

// --- Sonde température (capteur critique) ---
const rawTemp = g['sensor.temp_cumulus_petit_garage_temperature']?.state;
msg.tempAvailable =
    rawTemp !== undefined && rawTemp !== 'unavailable' && rawTemp !== 'unknown'
    && !isNaN(parseFloat(rawTemp));
msg.temp = msg.tempAvailable ? parseFloat(rawTemp) : null;

// --- Cumulus solaire amont (préchauffe en série, en amont du ballon élec.) ---
const rawSolarTemp = g['sensor.temp_cumulus_solaire_temperature']?.state;
msg.solarTempAvailable =
    rawSolarTemp !== undefined && rawSolarTemp !== 'unavailable' && rawSolarTemp !== 'unknown'
    && !isNaN(parseFloat(rawSolarTemp));
msg.solarTankTemp = msg.solarTempAvailable ? parseFloat(rawSolarTemp) : null;

// Suivi d'indisponibilité (pour notification en mode dégradé)
const nowMs = Date.now();
if (msg.tempAvailable) {
    setF('sondeDownSince', null);
    msg.sondeDownHours = 0;
} else {
    let ds = getF('sondeDownSince');
    if (!ds) { ds = nowMs; setF('sondeDownSince', ds); }
    msg.sondeDownHours = Math.round((nowMs - ds) / 360000) / 10;
}

// --- Autres mesures ---
msg.solar = n('sensor.powermeter_power_a', 0);
msg.gridPower = n('sensor.powermeter_power_b', 0);
msg.houseConsumption = n('sensor.powermeter_power_ab', 0);
msg.cumulusPower = n('sensor.cumulus_power', 0);
// Interrupteur : pas de coercition 'unavailable'→'off' (au reboot HA l'entité
// passe par 'unavailable'/'unknown' avant de se stabiliser). Repli sur le
// dernier état connu — évite une fausse « commande manuelle » en aval.
const rawSwitch = g['switch.cumulus']?.state;
msg.switchAvailable = rawSwitch === 'on' || rawSwitch === 'off';
msg.switchState = msg.switchAvailable ? rawSwitch : (getF('lastKnownSwitch') || 'off');
if (msg.switchAvailable) setF('lastKnownSwitch', rawSwitch);
msg.surplus = -msg.gridPower;

// --- Solcast (détaillé pour le slot par slot) ---
const sel = g['select.solcast_pv_forecast_utiliser_le_champ_de_prevision']?.state || 'estimate';
msg.forecastField = sel === 'estimate10' ? 'pv_estimate10'
    : sel === 'estimate90' ? 'pv_estimate90'
        : 'pv_estimate';
msg.forecastToday = attr('sensor.solcast_pv_forecast_previsions_pour_aujourd_hui', 'detailedForecast') || [];
msg.kwhToday = n('sensor.solcast_pv_forecast_previsions_pour_aujourd_hui', 0);
msg.kwhTodayRemaining = n('sensor.solcast_pv_forecast_previsions_de_production_restantes_aujourd_hui', 0);
msg.kwhTomorrow = n('sensor.solcast_pv_forecast_previsions_pour_demain', 0);

// --- Percentiles p10/p90 J+1 (incertitude) ---
msg.kwhTomorrowP10 = attrNum('sensor.solcast_pv_forecast_previsions_pour_demain', 'estimate10');
msg.kwhTomorrowP90 = attrNum('sensor.solcast_pv_forecast_previsions_pour_demain', 'estimate90');

// --- J+2 (après-demain) — fallback null si entité absente ---
msg.kwhDayAfter    = n('sensor.solcast_pv_forecast_prevision_jour_3', null);
msg.kwhDayAfterP10 = attrNum('sensor.solcast_pv_forecast_prevision_jour_3', 'estimate10');
msg.kwhDayAfterP90 = attrNum('sensor.solcast_pv_forecast_prevision_jour_3', 'estimate90');

const SOLCAST_MAX_AGE_MS = 6 * 3600 * 1000;
const solcastLU = g['sensor.solcast_pv_forecast_previsions_pour_aujourd_hui']?.last_updated;
const solcastAgeMs = solcastLU ? (Date.now() - new Date(solcastLU).getTime()) : Infinity;
msg.solcastStale = solcastAgeMs > SOLCAST_MAX_AGE_MS;
msg.solcastAgeHours = isFinite(solcastAgeMs) ? Math.round(solcastAgeMs / 360000) / 10 : null;

return msg;

// === Modulation météo : seuil solaire uniquement (cible fixe) ===
// La cible de température ne varie PLUS avec la météo : reachFor = target
// (le relèvement anti-légionelle reste appliqué en aval). Le forecast ne sert
// plus qu’à deux choses : moduler le SEUIL solaire (trigMult — démarrer la
// chauffe plus tôt quand les jours suivants sont mauvais, plus tard quand ils
// sont bons) et timer la fenêtre de forçage. Le remplissage solaire / surplus
// vise donc toujours la cible de confort.

// --- Constantes du modèle ---
const POOR_KWH = 6;    // kWh/j : seuil "pauvre"
const GOOD_KWH = 10;   // kWh/j : seuil "bon"

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const scoreFromKwh = (kwh) => clamp((kwh - POOR_KWH) / (GOOD_KWH - POOR_KWH), 0, 1);

// --- Scores continus, multi-jours (pire des 2 jours pilote trigMult) ---
const tomorrowScore = scoreFromKwh(msg.kwhTomorrow);
const dayAfterKwh = msg.kwhDayAfter != null ? msg.kwhDayAfter : msg.kwhTomorrow;
const worstNext2Kwh = Math.min(msg.kwhTomorrow, dayAfterKwh);
const worstScore = scoreFromKwh(worstNext2Kwh);

// --- Seuil solaire continu 0.9 → 1.1 (seul levier météo conservé) ---
const trigMult = 0.9 + 0.2 * worstScore;

// --- Cible FIXE : plus de modulation de température ---
// (l’override anti-légionelle éventuel est appliqué dans « Calc anti-légionelle »)
const reachFor = msg.target;

// --- Label lisible (rétro-compat dashboard) ---
let tomorrowMode;
if (worstScore < 0.25) tomorrowMode = 'poor';
else if (worstScore > 0.75) tomorrowMode = 'good';
else tomorrowMode = 'mixed';

// --- Sortie ---
msg.tomorrowMode = tomorrowMode;
msg.tomorrowScore = Math.round(tomorrowScore * 100) / 100;
msg.worstNext2Score = Math.round(worstScore * 100) / 100;
msg.worstNext2Kwh = Math.round(worstNext2Kwh * 10) / 10;
msg.trigMult = Math.round(trigMult * 1000) / 1000;
msg.reachFor = reachFor;  // arrondi final dans « Calc anti-légionelle »

return msg;

// === Anti-Legionella ===
// Pas de 60°C depuis 7j  -> relève la cible à 62°C (due)
// Pas de 60°C depuis 10j -> override critique (force ON, branche dédiée)
// v3 : forçage critique limité aux heures creuses (chauffe sur réseau).
//      Mettre LEGIO_CRITICAL_OFFPEAK_ONLY = false pour désactiver.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const LEGIO_TEMP_REACHED = 60;
const LEGIO_TARGET = 62;
const LEGIO_DUE_DAYS = 7;
const LEGIO_CRITICAL_DAYS = 10;
const DAY_MS = 24 * 3600 * 1000;
const LEGIO_CRITICAL_OFFPEAK_ONLY = true;
const OFFPEAK_START_H = 22;   // adapter au contrat (HC)
const OFFPEAK_END_H = 6;

const now = Date.now();
let lastHighTempAt = getF('lastHighTempAt');

// Init à la 1re exécution : évite un 'due' fantôme au déploiement
if (!lastHighTempAt) {
    lastHighTempAt = now;
    setF('lastHighTempAt', now);
}

// Mise à jour SEULEMENT si la sonde est OK
if (msg.tempAvailable && msg.temp >= LEGIO_TEMP_REACHED) {
    lastHighTempAt = now;
    setF('lastHighTempAt', now);
}

const sinceHighMs = now - lastHighTempAt;
msg.daysSinceHighTemp = Math.round(sinceHighMs / DAY_MS * 10) / 10;
msg.legionellaDue = sinceHighMs > LEGIO_DUE_DAYS * DAY_MS;

// Garde sur tempAvailable : null < 62 === true en JS sinon !
const rawCritical =
    sinceHighMs > LEGIO_CRITICAL_DAYS * DAY_MS
    && msg.tempAvailable
    && msg.temp < LEGIO_TARGET;

const h = new Date().getHours();
const inOffpeak = h >= OFFPEAK_START_H || h < OFFPEAK_END_H;
msg.legionellaCriticalPending = rawCritical;
msg.legionellaCritical = rawCritical && (!LEGIO_CRITICAL_OFFPEAK_ONLY || inOffpeak);

// Override cible si due (le label dashboard est porté par legionella_due)
if (msg.legionellaDue && msg.reachFor < LEGIO_TARGET) {
    msg.reachFor = LEGIO_TARGET;
}

// Finalisation
msg.reachFor = Math.round(msg.reachFor * 10) / 10;
msg.effectiveTrigger = Math.round(msg.solarTrig * msg.trigMult);
msg.forcageThreshold = msg.legionellaDue ? LEGIO_TEMP_REACHED : msg.minT;

return msg;

// === Anti-injection : éviter d'injecter du surplus dans le réseau ===
// cumulusDraw = mesure réelle si dispo.
// Fallback CUMULUS_LOAD_W uniquement pendant la "grace period" post-turn_on
// (le compteur peut ne pas avoir rafraîchi). Hors grace period, P<100W avec
// switch ON = thermostat mécanique ouvert → draw réel = 0 (pas de fantôme).

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = Date.now();
const HYST_MS = 5 * 60 * 1000;
const CUMULUS_LOAD_W = Number(env.get('CUMULUS_LOAD_W')) || 1200;
const CUMULUS_MIN_POWER_W = 100;
const STARTUP_GRACE_MS = 60 * 1000; // 60s, large pour compteurs lents

const lastActionAt = getF('lastActionAt') || 0;
const lastAction = getF('lastAction');
const justTurnedOn =
    lastAction === 'turn_on'
    && msg.switchState === 'on'
    && (now - lastActionAt) < STARTUP_GRACE_MS;

let cumulusDraw, thermostatTripped = false;
if (msg.switchState !== 'on') {
    cumulusDraw = 0;
} else if (msg.cumulusPower >= CUMULUS_MIN_POWER_W) {
    cumulusDraw = msg.cumulusPower;        // mesure réelle
} else if (justTurnedOn) {
    cumulusDraw = CUMULUS_LOAD_W;          // grace period : compteur pas encore rafraîchi
} else {
    cumulusDraw = 0;                       // thermostat mécanique coupé (ou panne)
    thermostatTripped = true;
}

const potentialSurplus = msg.surplus + cumulusDraw;

let highSince = getF('highSurplusSince');
let lowSince = getF('lowSurplusSince');

if (potentialSurplus > msg.surplusTrig) {
    if (!highSince) { highSince = now; setF('highSurplusSince', now); }
    setF('lowSurplusSince', null);
    msg.surplusHighFor5min = (now - highSince) > HYST_MS;
    msg.surplusLowFor5min = false;
} else {
    if (!lowSince) { lowSince = now; setF('lowSurplusSince', now); }
    setF('highSurplusSince', null);
    msg.surplusHighFor5min = false;
    msg.surplusLowFor5min = (now - lowSince) > HYST_MS;
}

let antiInjActive = getF('antiInjActive') || false;
if (msg.surplusHighFor5min) antiInjActive = true;
else if (msg.surplusLowFor5min) antiInjActive = false;
setF('antiInjActive', antiInjActive);

msg.potentialSurplus = Math.round(potentialSurplus);
msg.antiInjActive = antiInjActive;
msg.thermostatTripped = thermostatTripped;

// Légionelle critique mais thermostat mécanique coupé : chauffer est
// physiquement impossible → on n'use pas le relais, on notifie à la place.
msg.legionellaBlocked = false;
if (msg.legionellaCritical && thermostatTripped) {
    msg.legionellaCritical = false;
    msg.legionellaBlocked = true;
}

// Anti-injection "utile" : inutile de forcer ON si plus rien à absorber
// (cuve déjà à la cible ou thermostat mécanique coupé).
msg.antiInjUseful = antiInjActive
    && !thermostatTripped
    && !(msg.tempAvailable && msg.temp >= msg.reachFor);

// === Cumulus solaire amont : préchauffe en série ===
// Si le ballon solaire (en amont) fournit déjà l'eau à la cible — avec une
// marge anti-stratification / pertes en ligne — l'appoint électrique n'a rien
// à faire. On NE touche PAS à l'anti-injection ni à l'anti-légionelle : cette
// info n'est exploitée qu'à une priorité INFÉRIEURE dans l'arbre de décision.
// Marge réglable via la variable d'environnement SOLAR_SUFFICIENT_MARGIN (°C, défaut 3).
const _solarMarginRaw = parseFloat(env.get('SOLAR_SUFFICIENT_MARGIN'));
const SOLAR_SUFFICIENT_MARGIN = isNaN(_solarMarginRaw) ? 3 : _solarMarginRaw;
msg.solarSufficientMargin = SOLAR_SUFFICIENT_MARGIN;
msg.solarSufficientThreshold = Math.round((msg.reachFor + SOLAR_SUFFICIENT_MARGIN) * 10) / 10;
msg.solarCoversTarget =
    msg.solarTempAvailable === true
    && msg.solarTankTemp != null
    && msg.solarTankTemp >= msg.solarSufficientThreshold;

return msg;

// === Fenêtre optimale par intégration de la courbe Solcast ===
// v3 :
// - Dimensionnée sur le besoin de FORÇAGE (stopTemp - temp), pas sur reachFor :
//   le forçage est un filet de sécurité (minimum garanti), le chauffage nominal
//   reste piloté par le solaire / l'anti-injection.
// - Deadband : démarre sous forcageThreshold, s'arrête à forcageThreshold + 2°C.
// - Latch : fenêtre figée pendant le forçage (pas de flapping quand Solcast
//   rafraîchit sa courbe en cours de route).

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const CUMULUS_LOAD_W = Number(env.get('CUMULUS_LOAD_W')) || 1200;
const SLOT_MIN = 30;
const SLOT_MS = SLOT_MIN * 60 * 1000;
const FORCING_DEADBAND = 2; // °C au-dessus du seuil avant arrêt

const now = Date.now();
const stopTemp = Math.min(msg.forcageThreshold + FORCING_DEADBAND, msg.reachFor);

// Info dashboard : besoin pour la cible nominale
const dtInfo = msg.tempAvailable ? Math.max(msg.reachFor - msg.temp, 0) : 0;
// Dimensionnement : besoin pour garantir le minimum
const dtForcing = msg.tempAvailable ? Math.max(stopTemp - msg.temp, 0) : 0;

const energyKwh = msg.kwhPerDeg * dtForcing / msg.eff;
const durationMin = Math.ceil((energyKwh / (CUMULUS_LOAD_W / 1000)) * 60);
const slotsNeeded = Math.max(1, Math.ceil(durationMin / SLOT_MIN));

const MIN_AVG_W = msg.tomorrowMode === 'poor'
    ? CUMULUS_LOAD_W * 0.10
    : CUMULUS_LOAD_W * 0.30;

const field = msg.forecastField;
const slots = (msg.forecastToday || [])
    .map(s => ({
        t: new Date(s.period_start).getTime(),
        w: (s[field] || 0) * 1000
    }))
    .filter(s => s.t + SLOT_MS > now)
    .sort((a, b) => a.t - b.t);

let windowStart = null, windowEnd = null, windowAvgW = 0, windowOk = false;
let skipReason = null;

if (msg.solcastStale) {
    skipReason = 'Solcast périmé (' + msg.solcastAgeHours + 'h)';
} else if (!msg.tempAvailable) {
    skipReason = 'Sonde température indisponible';
} else if (dtForcing <= 0) {
    skipReason = 'Minimum déjà garanti';
} else if (slots.length < slotsNeeded) {
    skipReason = 'Pas assez de créneaux Solcast restants';
} else {
    let sum = 0;
    for (let i = 0; i < slotsNeeded; i++) sum += slots[i].w;
    let best = sum, bestIdx = 0;
    for (let i = slotsNeeded; i < slots.length; i++) {
        sum += slots[i].w - slots[i - slotsNeeded].w;
        if (sum > best) { best = sum; bestIdx = i - slotsNeeded + 1; }
    }
    windowStart = slots[bestIdx].t;
    windowEnd = slots[bestIdx + slotsNeeded - 1].t + SLOT_MS;
    windowAvgW = Math.round(best / slotsNeeded);

    if (windowAvgW >= MIN_AVG_W) {
        windowOk = true;
    } else {
        skipReason = 'Fenêtre trop faible (' + windowAvgW + 'W < ' + Math.round(MIN_AVG_W) + 'W)';
    }
}

// --- Latch de forçage (fenêtre figée + deadband) ---
let latch = getF('forcingLatch') || false;
let effStart = windowStart, effEnd = windowEnd;
if (latch) {
    const ls = getF('forcingWindowStart');
    const le = getF('forcingWindowEnd');
    if (ls && le) { effStart = ls; effEnd = le; }
}
const inWindow = effStart != null && now >= effStart && now <= effEnd;

if (!msg.tempAvailable || !inWindow) {
    latch = false;
} else if (!latch) {
    if (windowOk && msg.temp < msg.forcageThreshold) {
        latch = true;
        setF('forcingWindowStart', windowStart);
        setF('forcingWindowEnd', windowEnd);
    }
} else if (msg.temp >= stopTemp) {
    latch = false;
}
setF('forcingLatch', latch);

msg.dt = dtInfo;
msg.dtForcing = Math.round(dtForcing * 10) / 10;
msg.stopTemp = stopTemp;
msg.energyKwh = Math.round(energyKwh * 100) / 100;
msg.durationMin = durationMin;
msg.slotsNeeded = slotsNeeded;
msg.windowStart = effStart;
msg.windowEnd = effEnd;
msg.windowAvgW = windowAvgW;
msg.minAvgW = Math.round(MIN_AVG_W);
msg.windowSkippedReason = skipReason;
msg.inWindow = inWindow;
msg.isForcing = latch;

return msg;

// === Hystérésis solaire symétrique 5 min ===
// Seuil modulé par la météo de demain (effectiveTrigger).

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = Date.now();
const HYST_MS = 5 * 60 * 1000;
const trig = msg.effectiveTrigger;

let highSince = getF('highSolarSince');
let lowSince = getF('lowSolarSince');

if (msg.solar > trig) {
    if (!highSince) { highSince = now; setF('highSolarSince', now); }
    setF('lowSolarSince', null);
    msg.highFor5min = (now - highSince) > HYST_MS;
    msg.lowFor5min = false;
} else {
    if (!lowSince) { lowSince = now; setF('lowSolarSince', now); }
    setF('highSolarSince', null);
    msg.highFor5min = false;
    msg.lowFor5min = (now - lowSince) > HYST_MS;
}
return msg;

// === Détermine l'action + historique + détection commande manuelle ===
// action = turn_on / turn_off / none
// v3 : si l'interrupteur a été actionné hors du flow → pause de 45 min.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = Date.now();
const MANUAL_HOLD_MS = 45 * 60 * 1000;
const HA_LAG_GRACE_MS = 90 * 1000;   // tolérance de propagation d'état HA

// --- Détection commande manuelle ---
// Ignorée tant que l'état de l'interrupteur n'est pas exploitable
// (unavailable/unknown, typiquement pendant un reboot HA) : sinon chaque
// redémarrage déclencherait une fausse « commande manuelle » → pause de 45 min.
let expected = getF('expectedSwitch');
if (expected == null && msg.switchAvailable) { expected = msg.switchState; setF('expectedSwitch', expected); }
const prevActionAt = getF('lastActionAt') || 0;
let holdUntil = getF('manualHoldUntil') || 0;

if (msg.switchAvailable && expected != null
    && msg.switchState !== expected
    && (now - prevActionAt) > HA_LAG_GRACE_MS) {
    holdUntil = now + MANUAL_HOLD_MS;
    setF('manualHoldUntil', holdUntil);
    expected = msg.switchState;
    setF('expectedSwitch', expected);
    node.warn('Commande manuelle détectée → pause automatisation 45 min');
}

msg.manualHoldActive = msg.enabled && now < holdUntil;
if (msg.manualHoldActive) {
    msg.desired = msg.switchState;
    msg.state = 'Pause (commande manuelle)';
    msg.reason = 'Intervention manuelle détectée, reprise à '
        + new Date(holdUntil).toLocaleTimeString('fr-FR');
}
msg.manualHoldUntil = holdUntil > now ? holdUntil : null;

// --- Action ---
msg.action = 'none';
// On ne commande pas un interrupteur dont l'état n'est pas lisible
// (unavailable/unknown) : la commande échouerait et fausserait l'historique.
if (msg.switchAvailable && msg.desired !== msg.switchState) {
    msg.action = msg.desired === 'on' ? 'turn_on' : 'turn_off';
    setF('lastActionAt', now);
    setF('lastAction', msg.action);
    setF('lastActionReason', msg.reason);
    setF('expectedSwitch', msg.desired);
}

msg.lastActionAt = getF('lastActionAt');
msg.lastAction = getF('lastAction');
msg.lastActionReason = getF('lastActionReason');
msg.now = now;

return msg;

// === Alertes HA (persistent_notification) ===
// Une notification par épisode, anti-spam via contexte persistant.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const out = [];
const now = Date.now();

// 1. Sonde HS depuis ≥ 2 h (une notif par épisode)
if ((msg.sondeDownHours || 0) >= 2) {
    if (!getF('notifSondeDown')) {
        setF('notifSondeDown', true);
        out.push({ payload: {
            notification_id: 'cumulus_sonde_hs',
            title: 'Cumulus : sonde température HS',
            message: 'Sonde indisponible depuis ' + msg.sondeDownHours
                + ' h. Mode dégradé actif (solaire / anti-injection uniquement).'
        }});
    }
} else if (msg.tempAvailable) {
    setF('notifSondeDown', false);
}

// 2. Cycle anti-légionelle impossible (thermostat mécanique coupé avant 62°C)
if (msg.legionellaBlocked) {
    const last = getF('notifLegioBlockedAt') || 0;
    if (now - last > 24 * 3600 * 1000) {
        setF('notifLegioBlockedAt', now);
        out.push({ payload: {
            notification_id: 'cumulus_legio_blocked',
            title: 'Cumulus : cycle anti-légionelle impossible',
            message: msg.daysSinceHighTemp + ' j sans 60°C et le thermostat mécanique '
                + 'coupe avant la cible. Vérifier son réglage (≥ 62°C nécessaire).'
        }});
    }
}

if (out.length === 0) return null;
return [out];

// === Gestion des erreurs du flow (nœud catch) ===

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const src = (msg.error && msg.error.source) || {};
const SWITCH_NODES = ['695583ad1f4ba8e3', '62d66053da559b5c']; // turn_on / turn_off

// Commande switch échouée : l'historique optimiste est faux → purge,
// sinon la grace period anti-injection et la détection manuelle dérivent.
if (SWITCH_NODES.indexOf(src.id) !== -1) {
    setF('lastAction', null);
    setF('lastActionAt', 0);
    setF('expectedSwitch', null);
}

// Anti-spam : 1 notification max / 15 min
const now = Date.now();
const last = getF('lastErrorNotifAt') || 0;
if (now - last < 15 * 60 * 1000) return null;
setF('lastErrorNotifAt', now);

msg.payload = {
    notification_id: 'cumulus_flow_error',
    title: 'Cumulus : erreur dans le flow',
    message: (src.name || src.id || '?') + ' : '
        + (msg.error && msg.error.message ? msg.error.message : 'erreur inconnue')
};
return msg;
